import { describe, expect, it, vi } from "vitest";
import { readFileSync } from "node:fs";
import {
  canReadGmail,
  canMarkReplied,
  needsSendOnlyReconnect,
} from "@/lib/capabilities";
const gmail = vi.hoisted(() => vi.fn());
vi.mock("@/lib/gmail", () => ({ gmailForUser: gmail }));
import { checkOneReply, checkReplies, replyCandidates } from "@/lib/inngest";

describe("send-only boundary", () => {
  it("denies reads regardless of legacy grants or environment", async () => {
    vi.stubEnv("GMAIL_READ_ENABLED", "true");
    expect(canReadGmail()).toBe(false);
    expect(await checkOneReply("legacy-broad-grant-owner", "message")).toBe(
      false,
    );
    expect(await checkReplies("legacy-broad-grant-owner", true)).toEqual({
      checked: 0,
      replies: 0,
      disabled: true,
    });
    expect(await replyCandidates("legacy-broad-grant-owner", true)).toEqual([]);
    expect(gmail).not.toHaveBeenCalled();
    const source = readFileSync("src/lib/inngest.ts", "utf8");
    expect(source).not.toMatch(/users\.(threads\.get|messages\.(get|list))/);
    vi.unstubAllEnvs();
  });
  it("allows manual reply marking for active users", () => {
    expect(
      canMarkReplied({ id: "owner" }, { features: { markReplied: true } }),
    ).toBe(true);
    expect(
      canMarkReplied({ id: "owner", deletionRequestedAt: new Date() }),
    ).toBe(false);
    expect(canMarkReplied({ id: "" })).toBe(false);
  });
  it("distinguishes new send-only consent from unknown or broader grants", () => {
    expect(
      needsSendOnlyReconnect({ gmailScopes: [], gmailSendOnlyConsentAt: null }),
    ).toBe(true);
    expect(
      needsSendOnlyReconnect({
        gmailScopes: ["https://www.googleapis.com/auth/gmail.send"],
        gmailSendOnlyConsentAt: new Date(),
      }),
    ).toBe(false);
    expect(
      needsSendOnlyReconnect({
        gmailScopes: ["https://www.googleapis.com/auth/gmail.readonly"],
        gmailSendOnlyConsentAt: new Date(),
      }),
    ).toBe(true);
  });
});
